@import url('https://fonts.googleapis.com/css2?family=Michroma:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Formula 1 DNA — race red on carbon black, apex speed */
.theme-formula1 {
  --bg: oklch(0.164 0 0);
  --surface: oklch(0.205 0 0);
  --surface-2: oklch(0.252 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.686 0 0);
  --accent: oklch(0.573 0.233 29.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Michroma", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-formula1 h1,
.theme-formula1 h2,
.theme-formula1 h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-formula1 { --font-ui: var(--font-display); background-image: linear-gradient(180deg, oklch(0.2 0 0 / 60%), transparent 300px); }
.theme-formula1 h1, .theme-formula1 h2 { text-transform: uppercase; font-style: italic; }
.theme-formula1 h1::after { content: ""; display: block; height: 8px; width: 7rem; margin-top: 0.7rem; background: repeating-linear-gradient(45deg, var(--accent) 0 8px, #ffffff 8px 16px); }
.theme-formula1 button { text-transform: uppercase; font-style: italic; letter-spacing: 0.08em; }

/* depth */
.theme-formula1 { background-image: linear-gradient(180deg, oklch(0.2 0 0 / 60%), transparent 300px), repeating-linear-gradient(45deg, oklch(1 0 0 / 1.5%) 0 3px, transparent 3px 6px), repeating-linear-gradient(-45deg, oklch(1 0 0 / 1.5%) 0 3px, transparent 3px 6px); }
.theme-formula1 ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-formula1 thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.06em; font-size: 0.72em; background: oklch(0.13 0 0); border-bottom: 2px solid var(--accent); }
.theme-formula1 td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; font-family: var(--font-mono); font-size: 0.92em; }
.theme-formula1 tbody tr { border-left: 4px solid transparent; }
.theme-formula1 tbody tr:hover { background: oklch(0.24 0 0); border-left-color: var(--accent); }
.theme-formula1 a { color: var(--fg); font-weight: 600; text-decoration: none; border-bottom: 2px solid var(--accent); transition: color 100ms ease, letter-spacing 100ms ease; }
.theme-formula1 a:hover { color: var(--accent); letter-spacing: 0.02em; }
.theme-formula1 input, .theme-formula1 select, .theme-formula1 textarea { background: oklch(0.14 0 0); border: 1px solid oklch(1 0 0 / 20%); border-radius: var(--radius-sm); color: var(--fg); }
.theme-formula1 input:focus-visible, .theme-formula1 select:focus-visible, .theme-formula1 textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), 0 0 16px color-mix(in oklab, var(--accent) 50%, transparent); }
.theme-formula1 kbd { font-family: var(--font-display); font-size: 0.75em; background: oklch(0.13 0 0); border: 1px solid oklch(1 0 0 / 30%); border-radius: var(--radius-sm); padding: 0.15em 0.5em; }
.theme-formula1 .label-caps { font-family: var(--font-display); font-size: 0.7em; color: var(--fg-muted); }
.theme-formula1 .themed-border { border-left: 4px solid var(--accent); background-image: linear-gradient(90deg, color-mix(in oklab, var(--accent) 12%, transparent), transparent 40%); }
.theme-formula1 button { transition: transform 90ms ease, box-shadow 90ms ease; }
.theme-formula1 button:hover { transform: translateX(3px); box-shadow: -4px 0 0 var(--accent); }
.theme-formula1 button:active { transform: translateX(1px) scale(0.98); }
.theme-formula1 ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-formula1 ::-webkit-scrollbar-track { background: oklch(0.13 0 0); }
.theme-formula1 ::-webkit-scrollbar-thumb { background: oklch(0.35 0 0); border-radius: var(--radius-sm); }
.theme-formula1 ::-webkit-scrollbar-thumb:hover { background: var(--accent); }

/* alt mode: pit wall — daylight paddock white, race red kept sharp */
.theme-formula1.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --accent-2: oklch(0.17 0.005 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-formula1.alt-mode h1::after { background: repeating-linear-gradient(45deg, var(--accent) 0 8px, oklch(0.17 0.005 270) 8px 16px); }
.theme-formula1.alt-mode thead th { background: var(--fg); color: oklch(0.98 0 0); }
.theme-formula1.alt-mode tbody tr:hover { background: var(--surface-2); }
.theme-formula1.alt-mode input, .theme-formula1.alt-mode select, .theme-formula1.alt-mode textarea { background: oklch(1 0 0); border-color: oklch(0 0 0 / 25%); color: var(--fg); }
.theme-formula1.alt-mode kbd { background: var(--fg); color: oklch(0.98 0 0); border-color: var(--fg); }
.theme-formula1.alt-mode ::-webkit-scrollbar-track { background: var(--surface); }
.theme-formula1.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.70 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
